class Job:
    def run(self):
        self.vorher()
        print("arbeite")
        self.nachher()

    def vorher(self):
        print("start")

    def nachher(self):
        pass

class MeinJob(Job):
    def nachher(self):
        print("fertig")

    def run(self):
        print("eigen")

MeinJob().run()

